// Input order is fixed by the connections block: item 0 = Slack, item 1 = Drive, item 2 = Jira.
// A branch that failed (with onError: continueRegularOutput) surfaces as json.error on its item.
const items = $input.all();
const names = ["ciso", "compliance_drive", "ticket"];
const channels = [];
const failed_channels = [];

items.forEach((item, i) => {
  const name = names[i] || `branch_${i}`;
  if (item.json && item.json.error) {
    failed_channels.push(name);
  } else {
    channels.push(name);
  }
});

return [{ json: { channels, failed_channels } }];
